<?php
namespace App\Filament\Resources; use App\Filament\Resources\BackupResource\Pages; use App\Models\Backup; use App\Services\BackupService; use Filament\Notifications\Notification; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class BackupResource extends Resource {protected static ?string $model=Backup::class;protected static ?string $navigationIcon='heroicon-o-archive-box';protected static ?string $navigationLabel='Copias de seguridad';protected static ?string $modelLabel='copia';public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('filename')->label('Archivo'),Tables\Columns\TextColumn::make('type')->label('Tipo')->badge(),Tables\Columns\TextColumn::make('size')->label('Tamaño')->formatStateUsing(fn($state)=>number_format($state/1048576,1).' MB'),Tables\Columns\TextColumn::make('status')->label('Estado')->badge(),Tables\Columns\TextColumn::make('completed_at')->label('Finalizada')->dateTime('d/m/Y H:i')])->headerActions([Tables\Actions\Action::make('create')->label('Crear copia')->action(function(){app(BackupService::class)->create();Notification::make()->success()->title('Copia creada')->send();}),Tables\Actions\Action::make('full')->label('Exportación completa')->requiresConfirmation()->action(function(){app(BackupService::class)->create(true);Notification::make()->success()->title('Exportación creada')->send();})])->actions([Tables\Actions\Action::make('download')->label('Descargar')->url(fn(Backup $r)=>route('backups.download',$r))]);}public static function getPages():array{return['index'=>Pages\ListBackups::route('/')];}}
